class Super{
	int x=11,y=22;
	int method() {
		return (x<y? x: y);
	}
}
class Sub extends Super{
	int method() {
		return (x>y? x: y);
	}
}
public class TestSample {
	public static void main(String[] args) {
		Sub obj1=new Sub();
		Super obj2=new Sub();
		Super obj3=new Super();
		System.out.println(obj1.method());
		System.out.println(obj2.method());
		System.out.println(obj3.method());
	}
}
{15分，每个要点5分}

