abstract class Student {
    String name;
    String gender;
    public Student(String name, String gender) {
        this.name = name;
        this.gender = gender;
    }
    public abstract void study();
}
class Graduate extends Student {
    public Graduate(String name, String gender) {
        super(name, gender);
    }
    @Override
    public void study() {
        System.out.println(name + " （研究专科生）在进行专业研究学习。");
    }
}
class Undergraduate extends Student {
    public Undergraduate(String name, String gender) {
        super(name, gender);
    }
    @Override
    public void study() {
        System.out.println(name + " （本专科生）在进行专业知识学习。");
    }
}
class Junior extends Student {
    public Junior(String name, String gender) {
        super(name, gender);
    }
    @Override
    public void study() {
        System.out.println(name + " （专科生）在进行基本知识学习。");
    }
}
public class TestStudent {
	public static void main(String[] args) {
        Student stu;
        stu = new Graduate("李同学", "女");
        stu.study();
        stu = new Undergraduate("张同学", "男");
        stu.study();
        stu = new Junior("赵同学", "男");
        stu.study();
	}
}

questions.description:
(活动方式)、类变量(活动区域)和类方法(显示活动区域)。设计一个测试类完成各变量访
问和方法调用的测试。要求:进行构造方法、实例方法和类方法的重载。
{30分，根据功能完善度（70%），代码规范性（30%）给分}

questions.referenceAnswer:
class WildAnimal {
    private String bodySize;  // 实例变量：体型
    private static String activityArea = "森林";  // 类变量：活动区域
    public WildAnimal(String bodySize) {  // 构造方法1
        this.bodySize = bodySize;
    }
    public WildAnimal(String bodySize, String newActivityArea) {  // 构造方法2（重载）
        this.bodySize = bodySize;
        setActivityArea(newActivityArea);
    }
    public void move() {  // 实例方法1：活动方式
        System.out.println("野生动物在" + activityArea + "里活动。");
    }
    public void move(String extraInfo) {  // 实例方法2：活动方式（重载）
        System.out.println("野生动物在" + activityArea + "里活动。" + extraInfo);
    }
    public static void showActivityArea() {  // 类方法1：显示活动区域
        System.out.println("野生动物的活动区域是：" + activityArea);
    }
    public static void showActivityArea(String description) {  // 类方法2：显示活动区域（重载）
        System.out.println("野生动物的活动区域是：" + activityArea + "。" + description);
    }
    // 设置活动区域的方法（私有静态方法，仅供类内部使用）
    private static void setActivityArea(String newActivityArea) {
        activityArea = newActivityArea;
    }
}
public class TestAnimal {
	public static void main(String[] args) {
        WildAnimal animal1 = new WildAnimal("大型");  // 使用构造方法1创建对象
        animal1.move();  // 调用实例方法1
        WildAnimal animal2 = new WildAnimal("中型", "草原");  // 使用构造方法2创建对象
        animal2.move("它跑得很快。");  // 调用实例方法2
        WildAnimal.showActivityArea();  // 调用类方法1
        WildAnimal.showActivityArea("这是一个适合野生动物生存的地方。");  // 调用类方法2
	}
}
